import React from 'react';
import { Typography, Box, Divider, Chip, Accordion, AccordionSummary, AccordionDetails, Link, Alert } from '@mui/material';
import ReactMarkdown from 'react-markdown';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import MedicationIcon from '@mui/icons-material/Medication';
import CategoryIcon from '@mui/icons-material/Category';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import SourceIcon from '@mui/icons-material/Source';
import LocalHospitalIcon from '@mui/icons-material/LocalHospital';
import BiotechIcon from '@mui/icons-material/Biotech';
import MedicalInformationIcon from '@mui/icons-material/MedicalInformation';

const AnswerDisplay = ({ question, answer, loading, sources, questionType, processingTime }) => {
  if (!question && !answer) {
    return null;
  }

  // Function to determine medical icon based on question type
  const getMedicalIcon = (type) => {
    if (!type) return <MedicalInformationIcon />;

    if (type.includes('dosing') || type.includes('medication'))
      return <MedicationIcon />;
    else if (type.includes('procedure') || type.includes('test'))
      return <BiotechIcon />;
    else if (type.includes('eligibility') || type.includes('safety'))
      return <LocalHospitalIcon />;
    else
      return <MedicalInformationIcon />;
  };

  // Format the question type for display
  const formatQuestionType = (type) => {
    if (!type) return "General Query";
    return type
      .replace(/_/g, ' ')
      .split(' ')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  return (
    <Box>
      {question && (
        <Box sx={{ mb: 2 }}>
          <Typography variant="subtitle1" color="text.secondary" fontWeight={500}>
            Question:
          </Typography>
          <Typography variant="h6" gutterBottom fontWeight={600} sx={{ color: 'primary.dark' }}>
            {question}
          </Typography>
          <Divider sx={{ my: 2 }} />
        </Box>
      )}

      {loading ? (
        <Box sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="body1">Processing your clinical query...</Typography>
        </Box>
      ) : (
        answer && (
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
              {getMedicalIcon(questionType)}
              <Typography variant="h6" fontWeight={600} sx={{ ml: 1 }}>Clinical Response</Typography>
            </Box>

            <Alert severity="info" sx={{ mb: 3, fontSize: '0.9rem' }}>
              Information derived from protocol document analysis. Always consult with the principal investigator for final decisions.
            </Alert>

            <Box sx={{ mb: 3, px: 0.5 }}>
              <ReactMarkdown>{answer}</ReactMarkdown>
            </Box>

            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, mb: 3 }}>
              {questionType && (
                <Chip 
                  icon={<CategoryIcon />} 
                  label={`Query Type: ${formatQuestionType(questionType)}`} 
                  variant="outlined" 
                  color="primary" 
                  sx={{ fontWeight: 500 }}
                />
              )}
              {processingTime && (
                <Chip 
                  icon={<AccessTimeIcon />} 
                  label={`Response Time: ${processingTime.toFixed(2)}s`} 
                  variant="outlined" 
                  sx={{ fontWeight: 500 }}
                />
              )}
            </Box>

            {sources && sources.length > 0 && (
              <Accordion 
                sx={{ 
                  boxShadow: 'none', 
                  border: '1px solid rgba(0, 0, 0, 0.12)',
                  borderRadius: '8px', 
                  '&:before': { display: 'none' } 
                }}
              >
                <AccordionSummary 
                  expandIcon={<ExpandMoreIcon />}
                  sx={{ 
                    borderRadius: '8px',
                    backgroundColor: 'rgba(44, 82, 130, 0.04)',
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center' }}>
                    <SourceIcon color="primary" sx={{ mr: 1 }} />
                    <Typography fontWeight={500}>Protocol Sources ({sources.length})</Typography>
                  </Box>
                </AccordionSummary>
                <AccordionDetails sx={{ px: 2, pt: 2 }}>
                  {sources.map((source, index) => (
                    <Box 
                      key={index} 
                      sx={{ 
                        mb: 2, 
                        p: 2, 
                        backgroundColor: 'rgba(44, 82, 130, 0.03)', 
                        borderRadius: 2,
                        border: '1px solid rgba(44, 82, 130, 0.1)'
                      }}
                    >
                      <Typography variant="subtitle2" fontWeight={600} color="primary.dark">
                        {source.section_path || source.section_title}
                      </Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                        <span style={{ fontWeight: 500 }}>Relevance Score:</span> {(source.score * 100).toFixed(1)}%
                      </Typography>
                      <Typography variant="body2" sx={{ 
                        fontFamily: '"Roboto Mono", monospace',
                        fontSize: '0.85rem',
                        p: 1.5,
                        backgroundColor: 'rgba(255, 255, 255, 0.7)',
                        borderRadius: 1
                      }}>
                        {source.excerpt}
                      </Typography>
                    </Box>
                  ))}
                </AccordionDetails>
              </Accordion>
            )}
          </Box>
        )
      )}
    </Box>
  );
};

export default AnswerDisplay;
